async function getDashboardData() {
  try {
    const baseUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3000';

    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`).then(r => r.json()),
      fetch(`${baseUrl}/api/notifications`).then(r => r.json()),
      fetch(`${baseUrl}/api/settings`).then(r => r.json())
    ]);

    return { analytics, notifications, settings };
  } catch (error) {
    // Return mock data for build time or when API is unreachable
    console.warn('Fetching dashboard data failed, using mock data:', error);
    return {
      analytics: { 
        views: 5432, 
        uniqueVisitors: 1205,
        bounceRate: '42%'
      },
      notifications: [
        { id: 1, message: 'System maintenance scheduled for midnight', type: 'info' },
        { id: 2, message: 'New user registration milestone reached', type: 'success' },
        { id: 3, message: 'Failed login attempts detected', type: 'warning' }
      ],
      settings: { 
        theme: 'system', 
        emailNotifications: true,
        dataRefreshRate: 60
      }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div className="p-4 space-y-6">
      <h2 className="text-2xl font-bold">Dashboard Content</h2>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {/* Analytics Section */}
        <div className="border p-4 rounded shadow-sm">
          <h3 className="text-xl font-semibold mb-2">Analytics</h3>
          <div className="space-y-1">
            <p>Total Views: <span className="font-medium">{analytics.views.toLocaleString()}</span></p>
            <p>Unique Visitors: <span className="font-medium">{analytics.uniqueVisitors.toLocaleString()}</span></p>
            <p>Bounce Rate: <span className="font-medium">{analytics.bounceRate}</span></p>
          </div>
        </div>

        {/* Notifications Section */}
        <div className="border p-4 rounded shadow-sm">
          <h3 className="text-xl font-semibold mb-2">Notifications</h3>
          {notifications.length > 0 ? (
            <ul className="list-disc pl-5 space-y-1">
              {notifications.map((note: any) => (
                <li key={note.id} className="text-sm">{note.message}</li>
              ))}
            </ul>
          ) : (
            <p className="text-gray-500">No new notifications</p>
          )}
        </div>

        {/* Settings Section */}
        <div className="border p-4 rounded shadow-sm">
          <h3 className="text-xl font-semibold mb-2">Settings</h3>
          <div className="space-y-1">
            <p>Theme: <span className="capitalize">{settings.theme}</span></p>
            <p>Email Alerts: <span>{settings.emailNotifications ? 'On' : 'Off'}</span></p>
            <p>Refresh Rate: {settings.dataRefreshRate}s</p>
          </div>
        </div>
      </div>
    </div>
  );
}

